/* Formularios: un cambio de parámetro repinta sin perder lo escrito. */
function guardarCampos(e) { $$('input[id],textarea[id]', e.el).forEach(i => { if (i.type !== 'file' && i.type !== 'checkbox') e.params['_' + i.id] = i.value; }); }
