  d.innerHTML = '<div class="ill big">' + ilu(ilus) + '</div><h2 class="lg">' + esc(titulo) + '</h2><p class="mu">' + esc(texto) + '</p><button class="btn pri" style="margin-top:28px">Seguir</button>';
