  if (!await preguntar('¿Borrar «' + d.nombre + '»?', 'Se borra también el archivo cifrado de Drive.', 'Borrar', true)) return;
  cambiar('documentos', d.id, { _b: 1 }); paginasDe(d).forEach(x => api('archivo-borrar', { fid: x.fid }).catch(() => { }));
