  ['plantas', 'acuario', 'medicacion'].forEach(c => lista(c).filter(x => conRecuerdo(c, x) && en(x.proximo) && x.proximo > h).forEach(x => out.push([x.proximo, (c === 'plantas' ? 'Regar ' : '') + x.nombre, MODS[c][0], COL[RUTINAS[c].ci], 'rutVer" data-col="' + c, x.id])));
